# 把「更新卡片」狀態文字的翻譯加到 tw/hk/cn 的 _AutoGeneratedTranslations.txt（模擬器與 files\ 兩處）
# 重跑會先移除舊的這一段再重寫
import os
SIM = r'C:\Users\Gary\Desktop\WS模擬器'
REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
N = '\\n'                      # 翻譯檔裡的換行要寫成字面的 \n
L = '([^' + N + ']*)'
EN = ['Card storage: ', 'Last card update run: ', 'Card repo latest commit: ', 'Stage: ', 'Set: ', '']
ZH = ['卡片存放位置：', '上次更新卡片：', '卡片資料庫最新版本：', '階段：', '系列：', '']
TW = []
for k in (3, 4, 5, 6):
    key = N.join(EN[j] + L for j in range(k))
    val = N.join(ZH[j] + '$%d' % (j + 1) for j in range(k))
    TW.append('sr:"^' + key + '$"=' + val)
TW += [
    'sr:"^(.+) \\(([0-9]+)%\\)$"=$1（$2%）',
    'Checking installed images=檢查已安裝的圖片',
    'Checking metadata=檢查卡片資料',
    'Downloading new images=下載新圖片',
    'never=從未更新',
    'unavailable=無法取得',
    'loading...=讀取中…',
    'unknown=未知',
    'Card update complete. Card database reloaded; restart is not required.=卡片更新完成，已重新載入卡片資料，不需要重開遊戲。',
    'Card update completed, but the database could not be reloaded. Restart the game to load the updated cards.=卡片更新完成，但無法重新載入卡片資料，請重開遊戲以載入新卡片。',
    'Card update is already running.=卡片更新已在進行中。',
    'r:"^Card update failed: (.*)$"=卡片更新失敗：$1',
]
S2C = str.maketrans('檢查裝圖資料庫載從無讀階段係開遊戲進請新敗際', '检查装图资料库载从无读阶段系开游戏进请新败际')
MARK = '// --- 更新卡片狀態 ---'
for lang in ('tw', 'hk', 'cn'):
    lines = TW if lang != 'cn' else [l.translate(S2C) for l in TW]
    for root in (os.path.join(SIM, 'AutoTranslator'), os.path.join(REPO, 'files', 'AutoTranslator')):
        p = os.path.join(root, 'Translation', lang, 'Text', '_AutoGeneratedTranslations.txt')
        s = open(p, encoding='utf-8').read()
        if MARK in s: s = s[:s.index(MARK)]
        if not s.endswith('\n'): s += '\n'
        open(p, 'w', encoding='utf-8').write(s + MARK + '\n' + '\n'.join(lines) + '\n')
print('ok')
